import {NODES,NODE,EDGES,EXITS,EVENTS,ROLES,RES,createGame,neighbors,moveCost,escapeCheck,missionCheck,pursuitDistance,act,DIFFICULTIES,ruleSet,activePlayers,exitHeatLimit,denounceCheck,soloEscapeCheck} from './core.js';
import {SCENARIO,HOMES} from './story.js';
import {originLabel,campaignHTML,pursuitHTML,missionBoardHTML,localMissionsHTML,stealthHTML,briefingHTML,pursuitInfoHTML} from './campaign-ui.js';
import {difficultyPickerHTML,modePickerHTML,difficultyOptions,betrayalEntryHTML,betrayalMenuHTML,resultsHTML,gameRuleBadgesHTML} from './rules-ui.js';
import {actionScreenHTML,teamScreenHTML,compactBriefingHTML} from './play-ui.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE='tokyo-escape-save-v1';
let game=null,count=1,difficulty='normal',selected='kinshicho',uiScreen='action',navigationTarget=null,mapBooting=false,betrayalEnabled=false,roomSettings={difficulty:'normal',betrayal:false},setupRoles=[0,1,2,3],names=['','','',''],map,markers={},lines=[],base,baseOn=true,boundaries=null,toastTimer,online=null,peer=null,connections=new Map(),lobby=[],localSlot=0,networkTimeout,pursuerMarker;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function save(){if(game)try{localStorage.setItem(STORE,JSON.stringify(game))}catch{}}
function load(){try{const g=JSON.parse(localStorage.getItem(STORE));return validGame(g)?g:null}catch{return null}}
function validGame(g){return g&&[1,2,3].includes(g.version)&&validNewRules(g)&&validCampaign(g)&&['playing','won','lost'].includes(g.status)&&Array.isArray(g.players)&&g.players.length>=1&&g.players.length<=4&&g.players.every(p=>NODE[p.pos]&&Number.isInteger(p.role)&&p.role>=0&&p.role<4&&Number.isFinite(p.hp))&&Number.isInteger(g.turn)&&g.turn>=0&&g.turn<g.players.length&&g.resources&&Object.keys(RES).every(k=>Number.isFinite(g.resources[k]))&&Array.isArray(g.log)&&Array.isArray(g.searched)&&Number.isInteger(g.event)&&EVENTS[g.event]}

function validNewRules(g){return g.version<3||Object.hasOwn(DIFFICULTIES,g.difficulty)&&typeof g.betrayal==='boolean'&&Array.isArray(g.players)&&g.players.every((p,i)=>p.id===i&&typeof p.escaped==='boolean'&&typeof p.betrayalUsed==='boolean'&&typeof p.borderPass==='boolean')&&(g.status!=='playing'||!g.players[g.turn]?.escaped)}
function validCampaign(g){
 if(g.version===1)return !g.story&&!g.pursuit;
 return Array.isArray(g.players)&&!!SCENARIO[g.story?.scenario]&&Array.isArray(g.story.missions)&&g.story.missions.length===3&&g.story.missions.every((m,i)=>m.id===['proof','ally','transmit'][i]&&Array.isArray(m.nodes)&&m.nodes.length>0&&m.nodes.every(id=>NODE[id])&&typeof m.done==='boolean'&&m.need&&m.reward)&&g.pursuit&&NODE[g.pursuit.pos]&&Number.isInteger(g.pursuit.heat)&&g.pursuit.heat>=0&&g.pursuit.heat<=10&&Number.isInteger(g.pursuit.strikes)&&g.pursuit.strikes>=0&&g.players.every(p=>HOMES.some(h=>h.id===p.origin?.home));
}
function createRun(...args){let previousScenario;try{previousScenario=localStorage.getItem('tokyo-escape-last-story')}catch{}const g=createGame(...args,{previousScenario,betrayal:betrayalEnabled});try{localStorage.setItem('tokyo-escape-last-story',g.story.scenario)}catch{}return g}
function showBriefing(){if(game?.story){showModal(compactBriefingHTML(game));$('#briefing-close').onclick=closeModal}}
function showStory(){if(game?.story){showModal(briefingHTML(game));$('#briefing-close').textContent='行動画面へ戻る';$('#briefing-close').onclick=()=>{closeModal();setScreen('action')}}}
function renderCampaign(){
 $('#campaign').innerHTML=campaignHTML(game);$('#mission-board').innerHTML=missionBoardHTML(game);$('#mission-board').hidden=!game?.story;
 if($('#briefing-btn'))$('#briefing-btn').onclick=showStory;
 $$('[data-mission-locate]').forEach(b=>b.onclick=()=>{const m=game.story.missions.find(m=>m.id===b.dataset.missionLocate),from=game.players[game.turn].pos,target=[...m.nodes].sort((a,b)=>pursuitDistance(from,a)-pursuitDistance(from,b))[0];selectNode(target,false);toast(`${NODE[target].name}への道案内を表示しました。`)});
}

function showModal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){$('#modal').close()}
$('#modal-close').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
function renderSetup(){
 const saved=load(),rolesOpen=$('#role-options')?.open;
 $('#control-panel').innerHTML=`<h2>遊ぶ準備</h2><p class="panel-desc">人数と難易度を選んだら、すぐ出発できます。</p><div class="label-row"><label class="field-label">何人で遊ぶ？</label><small>この端末を交代で操作</small></div><div class="player-select">${[1,2,3,4].map(n=>`<button data-count="${n}" class="${count===n?'active':''}" aria-pressed="${count===n}">${n}<span>人</span></button>`).join('')}</div>${difficultyPickerHTML(difficulty)}${modePickerHTML(count,betrayalEnabled)}<details class="role-options" id="role-options" ${rolesOpen?'open':''}><summary>役割を選ぶ <span>おすすめを設定済み</span></summary><div class="roster">${Array.from({length:count},(_,i)=>{const r=ROLES[setupRoles[i]];return `<div class="role-row"><span class="role-symbol" style="color:${r.color}">${r.icon}</span><div><select aria-label="プレイヤー${i+1}の役割" data-role="${i}">${ROLES.map((x,j)=>`<option value="${j}" ${setupRoles[i]===j?'selected':''}>P${i+1} / ${x.name}</option>`).join('')}</select><small>${r.perk}</small></div></div>`}).join('')}</div></details><div class="start-area"><button class="primary" id="start-btn"><span>ゲームをはじめる</span><span>↗</span></button><p class="start-hint">初めてでも、画面の道案内で進められます。</p>${saved?.status==='playing'?'<button class="resume-btn" id="resume-btn">つづきから遊ぶ →</button>':''}</div>`;
 $$('[data-count]').forEach(b=>b.onclick=()=>{count=+b.dataset.count;renderSetup()});$$('[data-difficulty]').forEach(b=>b.onclick=()=>{difficulty=b.dataset.difficulty;renderSetup()});$$('[data-betrayal]').forEach(b=>b.onclick=()=>{betrayalEnabled=b.dataset.betrayal==='true';renderSetup()});$$('[data-role]').forEach(s=>s.onchange=()=>{setupRoles[+s.dataset.role]=+s.value;renderSetup()});
 $('#start-btn').onclick=()=>{if(saved?.status==='playing'){showModal('<span class="eyebrow">NEW EXPEDITION</span><h2>新しい遠征をはじめる</h2><p>保存されている遠征を、新しいチームの遠征に置き換えます。</p><div class="modal-actions"><button class="secondary" id="keep-save">もどる</button><button class="primary" id="confirm-start">新しく出発する ↗</button></div>');$('#keep-save').onclick=closeModal;$('#confirm-start').onclick=()=>{closeModal();startLocal()}}else startLocal()};if($('#resume-btn'))$('#resume-btn').onclick=()=>{game=load();selected=game.players[game.turn].pos;uiScreen='action';navigationTarget=null;render();focusPlayer();window.scrollTo({top:0,behavior:'instant'})};
}
function startLocal(){disconnect();game=createRun(count,difficulty,names,setupRoles);selected='kinshicho';uiScreen='action';navigationTarget=null;save();render();focusPlayer();window.scrollTo({top:0,behavior:'instant'});showBriefing()}
function canControl(){return !online||online.isHost&&!connections.get(game.turn)?.open||localSlot===game.turn}
function dispatch(action){
 if(!game||game.status!=='playing')return;
 if(online&&!online.isHost){if(!canControl()){toast('いまは仲間の行動順です。');return}const c=online.hostConnection;if(!c?.open){toast('ホストとの接続を確認してください。');return}c.send({type:'action',action});return}
 if(!canControl()){toast('いまは仲間の行動順です。');return}
 applyAction(action);
}
function applyAction(action){
 const prev=game.turn,prevPos=game.players[game.turn].pos,result=act(game,action);
 if(result.error){toast(result.error);return}
 game=result.state;
 if(prev!==game.turn||navigationTarget===game.players[game.turn].pos)navigationTarget=null;
 if(action.type==='move'||prev!==game.turn||prevPos!==game.players[game.turn].pos)selected=game.players[game.turn].pos;
 if(prev!==game.turn||game.status!=='playing')uiScreen='action';
 save();render();broadcastState();window.scrollTo({top:0,behavior:'instant'});
 if(action.type==='move')toast(`${NODE[game.players[prev].pos].name}に到着しました。`);
 else if(action.type==='search')toast('物資を見つけました。チーム全員で使えます。');
 else if(action.type==='mission')toast('任務クリア！ 次の目標を確認しましょう。');
 else if(action.type==='rest')toast('体力が回復しました。');
 else if(action.type==='hide')toast('追跡度を下げて、身を隠しました。');
 else if(action.type==='end')toast(`ラウンド${game.round}。街の状況：${EVENTS[game.event].name}`);
 if(prev!==game.turn){toast(`${game.players[game.turn].name}の番です。あと${game.ap}回行動できます。`);window.scrollTo({top:0,behavior:'instant'})}
 if(action.type==='soloEscape'&&game.status==='playing')toast('単独脱出しました。残った人の遠征は続きます。');
 if(game.status==='won')toast('脱出成功！ 結果を確認できます。');
}
function bindScreens(){$$('[data-screen]').forEach(b=>b.onclick=()=>setScreen(b.dataset.screen))}
async function setScreen(screen,scroll=true){
 if(!['action','map','missions','team'].includes(screen))screen='action';
 if(screen!=='map'&&map)map.stop();
 uiScreen=screen;document.body.dataset.screen=screen;
 $$('#game-tabs [data-screen]').forEach(b=>{if(b.dataset.screen===screen)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
 if(scroll)window.scrollTo({top:0,behavior:'instant'});
 if(screen==='map'&&!map&&!mapBooting){mapBooting=true;try{await initMap()}finally{mapBooting=false}}
 if(uiScreen==='map'&&map){requestAnimationFrame(()=>{if(uiScreen!=='map')return;map.stop();map.invalidateSize();const n=NODE[selected]||NODE[game?.players[game.turn]?.pos||'kinshicho'];map.setView([n.lat,n.lng],Math.max(map.getZoom(),11),{animate:false})})}
}
function render(){
 document.body.classList.toggle('game-open',!!game);document.body.dataset.status=game?.status||'setup';
 $('#game-tabs').hidden=!game;
 renderCampaign();renderRoutes();updateMap();
 if(!game){renderSetup();$('#team-screen').innerHTML='';return}
 $('#team-screen').innerHTML=teamScreenHTML(game);
 $$('[data-find]').forEach(b=>b.onclick=()=>selectNode(game.players[+b.dataset.find].pos,true,'map'));
 $('#team-story').onclick=showStory;
 $('#tab-mission-count').textContent=game.story?game.story.missions.filter(m=>m.done).length+'/3':'';
 renderGame();$('#log-title').textContent='最近のできごと';$('#log').innerHTML=game.log.slice(0,12).map(l=>`<div class="log-item"><span>${l.round}R</span><div>${escape(l.text)}</div></div>`).join('');
 bindScreens();setScreen(uiScreen,false);
}
function renderGame(){
 if(game.status!=='playing'){renderEnd();return}
 $('#control-panel').innerHTML=actionScreenHTML(game,{control:canControl(),online,localSlot,navigationTarget});
 const actions={'search-btn':'search','rest-btn':'rest','hide-btn':'hide','decoy-btn':'decoy','escape-btn':'escape','end-turn':'end'};
 for(const[id,type]of Object.entries(actions))if($('#'+id))$('#'+id).onclick=()=>dispatch({type});
 $$('[data-quick-to]').forEach(b=>b.onclick=()=>quickMove(b.dataset.quickTo,b.dataset.quickMode));
 $$('[data-perform-mission]').forEach(b=>b.onclick=()=>dispatch({type:'mission',id:b.dataset.performMission}));
 if($('#cancel-navigation'))$('#cancel-navigation').onclick=()=>{navigationTarget=null;renderGame()};
 if($('#betrayal-btn'))$('#betrayal-btn').onclick=showBetrayal;
 if($('#pursuit-info'))$('#pursuit-info').onclick=()=>showModal(pursuitInfoHTML(game));
 if($('#take-over'))$('#take-over').onclick=()=>{const c=connections.get(game.turn);connections.delete(game.turn);if(c)c.close();renderGame();toast('ホストが操作を引き継ぎました。')};
 bindScreens();
}
function quickMove(to,mode){
 const cost=moveCost(game,to,mode);if(cost.error){toast(cost.error);return}
 if(game.pursuit?.pos===to&&!game.pursuit.stunned){showModal(`<h2>追跡隊がいる場所です</h2><p>${NODE[to].name}に入ると拘束されます。先に通信機で「陽動する」と、通れるようになります。</p><div class="modal-actions"><button class="secondary" id="cancel-danger">やめておく</button><button class="betray-confirm" id="confirm-danger">それでも進む</button></div>`);$('#cancel-danger').onclick=closeModal;$('#confirm-danger').onclick=()=>{closeModal();dispatch({type:'move',to,mode})};return}
 dispatch({type:'move',to,mode});
}
function quitGame(){
 save();const leave=()=>{disconnect();game=null;navigationTarget=null;uiScreen='action';closeModal();render();window.scrollTo({top:0,behavior:'instant'})};
 if(online){showModal('<h2>保存して、ルームを離れる</h2><p>ホストが離れると通信が終了します。最後に同期した状態は各端末に保存され、1台でのプレイを続けられます。</p><div class="modal-actions"><button class="secondary" id="stay-room">続けて遊ぶ</button><button class="primary" id="leave-room">保存して戻る</button></div>');$('#stay-room').onclick=closeModal;$('#leave-room').onclick=leave}else leave();
}
function showMenu(){showModal(`<h2>メニュー</h2><div class="menu-list">${game?'<button id="menu-story">今回の物語・ルール</button><button id="menu-home">保存して最初の画面へ</button>':''}<button id="menu-help">遊び方を見る</button><button id="menu-online">友達とオンラインで遊ぶ</button></div>`);if($('#menu-story'))$('#menu-story').onclick=showStory;if($('#menu-home'))$('#menu-home').onclick=quitGame;$('#menu-help').onclick=showHelp;$('#menu-online').onclick=showNetwork}
$('#menu-btn').onclick=showMenu;
function showHelp(){showModal(`<h2>遊び方は、3つだけ。</h2><ol class="quick-rules"><li><b>1</b><div><strong>自分の番に、2回行動</strong><span>行き先の「電車」「徒歩」を押すと移動。探索や休息も1行動です。</span></div></li><li><b>2</b><div><strong>「いま、やること」を進める</strong><span>必要な場所と、次の一歩を画面が案内します。任務の場所に着いたら、緑の実行ボタンを押そう。</span></div></li><li><b>3</b><div><strong>2回行動したら、下の「次へ」</strong><span>全員が行動するとラウンドが進みます。任務と物資をそろえて、同じ出口に集まろう。</span></div></li></ol><p>体力が少ない →「休む」<br>追跡度が高い →「隠れる」<br>場所を見たい → 下の「地図」</p><button class="primary" id="help-close">わかった、遊んでみる →</button><button class="secondary full" id="full-rules">裏切り・役割など、くわしいルール</button>`);$('#help-close').onclick=closeModal;$('#full-rules').onclick=showDetailedRules}
function renderEnd(){
 const won=game.status==='won',e=EXITS.find(e=>e.id===game.ending),escaped=game.version<3&&won?game.players.length:game.players.filter(p=>p.escaped).length,individual=game.players.some(p=>p.escapeKind==='solo'),title=won?(individual?'それぞれの帰国。':'全員、脱出成功。'):escaped?'帰国できた人、残された人。':'遠征はここまで。';
 $('#control-panel').innerHTML=`<div class="panel-step">EXPEDITION ${won?'COMPLETE':'ENDED'}<span>R ${Math.min(game.round,game.limit)}</span></div>${gameRuleBadgesHTML(game)}<div class="end-screen"><div class="end-symbol">${escaped?'↗':'⌁'}</div><span class="eyebrow">${won?'RETURN HOME':'EXPEDITION RESULTS'}</span><h2>${title}</h2><p>${won?(e?escape(e.name)+'から、残っていた全員が帰国した。':'それぞれの出口から帰国した。'):game.ending==='captured'?ruleSet(game).strikeLimit+'度の拘束により、残った人の国境が閉ざされた。':game.ending==='time'?'残った人の脱出時間が尽きてしまった。':'残った人の食料と体力が尽きてしまった。'}</p>${resultsHTML(game)}${game.story?`<div class="end-story">${escape(SCENARIO[game.story.scenario].title)}<br>任務 ${game.story.missions.filter(m=>m.done).length}/3 · 拘束 ${game.pursuit.strikes}/${ruleSet(game).strikeLimit}</div>`:''}<div class="end-score"><strong>${escaped}/${game.players.length}</strong>人が脱出 <span style="margin-left:15px"><strong>${Math.min(game.round,game.limit)}</strong>ラウンド</span></div><button class="primary" id="restart-btn"><span>新しい脱出計画へ</span><span>↗</span></button></div>`;
 $('#restart-btn').onclick=()=>{disconnect();game=null;selected='kinshicho';navigationTarget=null;uiScreen='action';render()};
}
function renderRoutes(){$('#routes').innerHTML=EXITS.map(e=>`<button class="route-card ${game?.goal===e.id?'active':''}" data-route="${e.id}" aria-label="${e.name}の脱出条件"><div class="route-head"><span class="route-icon" style="color:${e.color}">${e.icon}</span><span>${e.en}</span></div><h3>${e.name}</h3><div class="route-tag"><b>${e.tag}</b><span>${e.risk}</span></div><div class="route-need">${Object.entries(e.need).map(([k,v])=>`<span style="color:${RES[k].color}">${RES[k].icon} ${RES[k].label} ${v}</span>`).join('')}</div></button>`).join('');$$('[data-route]').forEach(b=>b.onclick=()=>showRoute(b.dataset.route))}
function showRoute(id){const e=EXITS.find(e=>e.id===id),c=game?escapeCheck(game,id):null;showModal(`<span class="eyebrow">${e.en} / ESCAPE ROUTE</span><div class="modal-icon" style="color:${e.color}">${e.icon}</div><h2>${e.name}</h2><p>${e.desc}</p><h3>脱出の条件</h3><p>未脱出の全員が<strong>${NODE[e.node].name}</strong>に集合し、次の共有物資をそろえる。</p><div class="modal-need">${Object.entries(e.need).map(([k,v])=>`<span style="color:${RES[k].color}">${RES[k].icon} ${RES[k].label}<strong>${v}</strong>${game?` / 現在${game.resources[k]}`:''}</span>`).join('')}</div>${game?.story?`<p class="network-tip">協力脱出：3任務を達成し、未脱出の全員が集合。追跡度は${exitHeatLimit(game)}以下。${game.betrayal?'単独脱出の条件は「裏切りの選択」で確認できます。':''}</p>`:''}${c?`<p>${c.ok?'✓ 条件を達成しています。':escape(c.reasons.join(' / '))}</p>`:''}<p class="network-tip">${e.id==='mountain'?'山道には山装備が1つ以上必要。移動で体力を消耗します。登山家を入れると進みやすくなります。':'鉄道が止まっても徒歩で移動できます。体力が減ったら、食料を使って休息しましょう。'}</p><div class="modal-actions"><button class="secondary" id="view-route">地図で見る ◎</button>${game?.status==='playing'?`<button class="primary" id="set-goal" ${!canControl()?'disabled':''}>目標ルートにする ↗</button>`:''}</div>`);$('#view-route').onclick=()=>{closeModal();selectNode(e.node,true,'map');if(!game)toast(`${e.name}：${e.desc}`)};if($('#set-goal'))$('#set-goal').onclick=()=>{dispatch({type:'goal',goal:id});closeModal();toast(`目標を「${e.name}」に設定しました。`)}}
function showTeam(){showModal(`<span class="eyebrow">TEAM STATUS</span><h2>チームの帰国状況</h2><div class="roster">${game.players.map((p,i)=>`<div class="role-row"><span class="role-symbol" style="color:${ROLES[p.role].color}">${i+1}</span><div><strong>${escape(p.name)} / ${ROLES[p.role].name}</strong>${p.origin?`<small class="player-origin">${escape(originLabel(p))}</small>`:''}<small>${p.escaped?'✓ 帰国済み / '+escape(EXITS.find(e=>e.id===p.escapeExit)?.name||''):NODE[p.pos].name+' · 体力 '+p.hp+'/8'}${!p.escaped&&game.turn===i?' · 行動中':''}</small><small>${ROLES[p.role].perk}</small></div><button class="secondary" data-find="${p.id}">地図 ◎</button></div>`).join('')}</div><p>物資はチームで共有しています。協力脱出では未脱出の全員が同じ出口に集合します。脱出した人は行動順から外れます。</p>`);$$('[data-find]').forEach(b=>b.onclick=()=>{closeModal();selectNode(game.players[+b.dataset.find].pos,true,'map')})}
function showBetrayal(){
 if(!game?.betrayal||game.status!=='playing')return;
 showModal(betrayalMenuHTML(game,canControl()));
 $$('[data-denounce]').forEach(b=>b.onclick=()=>{
  const check=denounceCheck(game,+b.dataset.denounce);if(!check.ok){toast(check.reasons.join(' / '));return}
  showModal(`<span class="eyebrow">BETRAY A TEAMMATE</span><h2>${escape(check.target.name)}を密告する</h2><p>居場所「${NODE[check.target.pos].name}」が追跡隊に伝わり、対象の潜伏を解除、追跡度が3上がります。あなたは単独脱出時の追跡度条件を免除する個人通行証を得ます。</p><p class="network-tip">1行動を消費。密告は1人1回。実行した人と対象は遠征ログで全員に伝わります。</p><div class="modal-actions"><button class="secondary" id="cancel-denounce">考え直す</button><button class="betray-confirm" id="confirm-denounce">密告を実行する →</button></div>`);
  $('#cancel-denounce').onclick=showBetrayal;$('#confirm-denounce').onclick=()=>{closeModal();dispatch({type:'denounce',target:check.target.id})};
 });
 $('#solo-escape-btn').onclick=()=>{
  const check=soloEscapeCheck(game);if(!check.ok){toast(check.reasons.join(' / '));return}
  showModal(`<span class="eyebrow">LEAVE WITHOUT THE OTHERS</span><h2>自分だけ、帰国する。</h2><p>「${check.exit.name}」から単独脱出します。共有物資の${Object.entries(check.need).map(([k,v])=>RES[k].label+v).join('・')}を消費し、あなたは観戦になります。残された人の任務・追跡・脱出は続きます。</p><div class="modal-actions"><button class="secondary" id="cancel-solo">仲間を待つ</button><button class="betray-confirm" id="confirm-solo">単独脱出を実行 →</button></div>`);
  $('#cancel-solo').onclick=showBetrayal;$('#confirm-solo').onclick=()=>{closeModal();dispatch({type:'soloEscape'})};
 };
}

function selectNode(id,pan=false,view='action'){
 if(!NODE[id]||!game)return;
 selected=id;navigationTarget=id===game.players[game.turn].pos?null:id;
 renderGame();updateMap();setScreen(view);
 if(pan&&map&&view==='map')map.setView([NODE[id].lat,NODE[id].lng],11,{animate:false});
}
function focusPlayer(){const n=NODE[game?game.players[game.turn].pos:'kinshicho'];if(map&&uiScreen==='map'&&map.getContainer().clientWidth){map.stop();map.invalidateSize();map.setView([n.lat,n.lng],11,{animate:false})}}
async function initMap(){
 if(!window.L){fallbackMap();return}
 map=L.map('map',{zoomControl:false,maxBounds:[[34.7,138.25],[37.25,141.2]],maxBoundsViscosity:1,minZoom:8,maxZoom:13,zoomSnap:.5,attributionControl:true}).setView([35.72,139.63],10);
 L.control.zoom({position:'bottomright'}).addTo(map);
 map.attributionControl.setPrefix('');
 map.createPane('border');map.getPane('border').style.zIndex=250;map.createPane('regions');map.getPane('regions').style.zIndex=280;
 const geoFetch=fetch('kanto.geojson').then(r=>{if(!r.ok)throw Error();return r.json()});
 try{boundaries=await geoFetch;L.geoJSON(boundaries,{pane:'border',interactive:false,style:f=>({color:f.properties.id===13?'#d2ac68':'#779580',weight:f.properties.id===13?1.8:1,opacity:.7,fillColor:f.properties.id===13?'#897443':'#31463b',fillOpacity:f.properties.id===13?.17:.14})}).addTo(map);$('#map-status').textContent='関東7都県のみ / 境界データ読込済み';map.attributionControl.addAttribution('<a href="https://github.com/dataofjapan/land" target="_blank" rel="noopener">境界: Data of Japan</a>')}
 catch{$('#map-status').textContent='境界データを取得できません。ルート地図でプレイできます。'}
 const KantoTile=L.TileLayer.extend({createTile(coords,done){if(boundaries&&!tileIntersectsKanto(coords)){const el=document.createElement('div');setTimeout(()=>done(null,el),0);return el}return L.TileLayer.prototype.createTile.call(this,coords,done)}});
 base=new KantoTile('https://cyberjapandata.gsi.go.jp/xyz/pale/{z}/{x}/{y}.png',{bounds:[[34.85,138.35],[37.2,140.99]],minZoom:8,maxZoom:13,maxNativeZoom:13,attribution:'<a href="https://maps.gsi.go.jp/development/ichiran.html" target="_blank" rel="noopener">地理院タイル</a> | Shoreline: VMAP0, USGS (1997)',opacity:.7,keepBuffer:0,updateWhenIdle:true});base.addTo(map);
 let tileCount=0,failed=0;base.on('tileload',()=>{tileCount++;$('#map-status').textContent='ONLINE MAP / 関東7都県の地図データ'});base.on('tileerror',()=>{if(++failed>3&&!tileCount)$('#map-status').textContent='地形画像を取得できません。関東境界・ルート地図でプレイできます。'});
 const labels=[['東京都',35.59,139.34],['神奈川県',35.37,139.27],['埼玉県',36.04,139.37],['千葉県',35.40,140.25],['茨城県',36.38,140.25],['栃木県',36.76,139.62],['群馬県',36.55,138.99]];
 labels.forEach(([name,lat,lng])=>L.marker([lat,lng],{pane:'regions',interactive:false,icon:L.divIcon({className:'pref-label',html:name,iconSize:[100,20],iconAnchor:[45,10]})}).addTo(map));
 EDGES.forEach(e=>{const a=NODE[e.a],b=NODE[e.b];const line=L.polyline([[a.lat,a.lng],[b.lat,b.lng]],{color:e.type==='loop'?'#9ac98e':e.type==='mountain'||e.type==='foot'?'#e8b96e':'#7ea7a0',weight:e.type==='loop'?3:2,opacity:.65,dashArray:['mountain','foot'].includes(e.type)?'5,6':null}).addTo(map);line.bindTooltip(e.name,{sticky:true});lines.push({line,edge:e})});
 NODES.forEach(n=>{markers[n.id]=L.marker([n.lat,n.lng],{icon:nodeIcon(n),keyboard:true,title:n.name,zIndexOffset:n.exit?100:0}).addTo(map).on('click',()=>selectNode(n.id))});map.on('zoomend',updateMap);updateMap();
}
function insideRing(x,y,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])inside=!inside}return inside}
function tileIntersectsKanto(c){const size=256;const nw=map.unproject([c.x*size,c.y*size],c.z),se=map.unproject([(c.x+1)*size,(c.y+1)*size],c.z);const points=[[nw.lng,nw.lat],[se.lng,nw.lat],[se.lng,se.lat],[nw.lng,se.lat],[(nw.lng+se.lng)/2,(nw.lat+se.lat)/2]];return boundaries.features.some(f=>f.geometry.coordinates.some(poly=>{const ring=poly[0];return points.some(([x,y])=>insideRing(x,y,ring))||ring.some(([x,y])=>x>=nw.lng&&x<=se.lng&&y<=nw.lat&&y>=se.lat)}))}
function nodeIcon(n){const here=game?.players.filter(p=>!p.escaped&&p.pos===n.id)||[],reach=game?neighbors(game.players[game.turn].pos).some(e=>e.to===n.id):false;const mission=game?.story?.missions.find(m=>!m.done&&m.nodes.includes(n.id));const major=!!mission||n.exit||['kinshicho','shinjuku','ueno','tachikawa','okutama','kashiwa','chiba','mito','utsunomiya','takasaki'].includes(n.id),show=(map?.getZoom()>=11.5)||major||here.length||selected===n.id;return L.divIcon({className:'node-wrap',html:`<button tabindex="-1" class="node-btn ${n.exit?'exit':''} ${selected===n.id?'selected':''} ${reach?'reachable':''} ${game?.searched.includes(n.id)?'searched':''} ${mission?'mission-node':''}" aria-label="${n.name}"><span class="node-point"></span>${mission?`<span class="map-mission-badge">${{proof:'A',ally:'B',transmit:'C'}[mission.id]}</span>`:''}${show?`<span class="node-label">${n.name}</span>`:''}${here.length?`<span class="player-pips">${here.map(p=>`<span class="player-pip" style="background:${ROLES[p.role].color}">${p.id+1}</span>`).join('')}</span>`:''}</button>`,iconSize:[1,1],iconAnchor:[0,0]})}
function updateMap(){if(!map){if($('#map-fallback svg'))fallbackMap();return}NODES.forEach(n=>markers[n.id]?.setIcon(nodeIcon(n)));if(game){const p=game.players[game.turn];$('.map-note').innerHTML=`<span>ROUND ${String(game.round).padStart(2,'0')} / TEAM POSITION</span><strong>${escape(p.name)} / ${NODE[p.pos].name}</strong><small>明るい地点を選んで、次の一歩を。</small>`}updatePursuer();lines.forEach(({line,edge:e})=>{line.setStyle({opacity:game&&[e.a,e.b].includes(game.players[game.turn].pos)?.95:.48,color:e.type==='loop'&&game&&EVENTS[game.event].kind==='blackout'?'#a56d65':e.type==='loop'?'#9ac98e':['mountain','foot'].includes(e.type)?'#e8b96e':'#7ea7a0'})})}
function updatePursuer(){if(!map)return;if(!game?.pursuit){if(pursuerMarker){pursuerMarker.remove();pursuerMarker=null}return}const q=game.pursuit,n=NODE[q.pos],icon=L.divIcon({className:'pursuer-marker',html:`<span class="pursuer-dot">!</span><span class="pursuer-label">追跡隊${q.stunned?' / 陽動中':''}</span>`,iconSize:[30,38],iconAnchor:[15,44]});if(!pursuerMarker)pursuerMarker=L.marker([n.lat,n.lng],{icon,zIndexOffset:600,title:'追跡隊：'+n.name}).addTo(map).on('click',()=>showModal(pursuitInfoHTML(game)));else pursuerMarker.setLatLng([n.lat,n.lng]).setIcon(icon)}
function fallbackMap(){const el=$('#map-fallback');el.hidden=false;const project=n=>[50+(n.lng-138.9)*430,420-(n.lat-35.35)*300];el.innerHTML=`<svg viewBox="0 0 850 530" role="img" aria-label="関東の簡略ルート地図"><defs><pattern id="grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0V30" fill="none" stroke="#29423a" stroke-width=".5"/></pattern></defs><rect width="850" height="530" fill="url(#grid)"/>${EDGES.map(e=>{const a=project(NODE[e.a]),b=project(NODE[e.b]);return `<path d="M${a}L${b}" fill="none" stroke="${e.type==='loop'?'#94be81':'#698e80'}" stroke-width="2" ${e.type==='mountain'?'stroke-dasharray="5 5"':''}/>`}).join('')}${NODES.map(n=>{const[x,y]=project(n);return `<g class="fallback-node" data-map-node="${n.id}" tabindex="0" role="button" aria-label="${n.name}" transform="translate(${x},${y})"><circle r="${n.exit?7:4}"/><text x="9" y="4">${n.name}</text></g>`}).join('')}</svg>`;$$('[data-map-node]').forEach(b=>{b.onclick=()=>selectNode(b.dataset.mapNode);b.onkeydown=e=>{if(e.key==='Enter')selectNode(b.dataset.mapNode)}});$('#map-status').textContent='簡略ルート地図 / 地図ライブラリを読み込めませんでした。'}
$('#focus-btn').onclick=focusPlayer;$('#overview-btn').onclick=()=>map?.fitBounds([[34.96,138.55],[37.15,140.91]],{padding:[20,20]});$('#base-btn').onclick=()=>{if(!map||!base)return;baseOn=!baseOn;if(baseOn)base.addTo(map);else base.remove();$('#base-btn').textContent=`地形 ${baseOn?'ON':'OFF'}`;$('#base-btn').setAttribute('aria-pressed',String(baseOn))};
$('#rules-btn').onclick=()=>showModal(`<span class="eyebrow">HOW TO PLAY</span><h2>全員で、東京の外へ。</h2><p>東京都が突然、独立国家「東京国」を宣言。近県から通勤・通学・観光に来ていたあなたたちは、県外住民だと発覚し、追跡の対象になりました。東東京・錦糸町から、全員で故郷への帰国を目指します。</p><ol><li><strong>探索して物資を集める。</strong> 食料・乗車券・山装備・通信機は全員で共有。各地点はチームで1回だけ探索できます。</li><li><strong>1人ずつ、2回行動。</strong> 移動・探索・休息はそれぞれ1行動。「交代」を押すと次の人へ。全員が行動すると1ラウンドが終わり、1人につき食料を1消費します。</li><li><strong>鉄道か、徒歩か。</strong> 鉄道は乗車券を消費。徒歩は体力を2消費します。山道は体力を4消費し、山装備が1つ以上必要。休息は食料1で体力を4回復します。</li><li><strong>同じ出口に、全員集合。</strong> 3つの帰国任務を達成し、追跡度を下げ、5つのルートから出口を選んで必要な物資をそろえると「全員で脱出」が押せます。最後のラウンド中までに脱出しましょう。</li></ol><h3>3つの帰国任務と追跡</h3><p>毎回異なる場所で、証明書の回収・仲間や都民協力者の救出・県外への通信を行います。A・B達成後にCの送信が可能。複数人プレイの救出は2人が同じ地点に集まる必要があります。すべて必須で、任務は探索とは別に1行動を使います。</p><p>鉄道・探索・任務は追跡度を上げ、追跡隊は最後の目撃地点を追います。徒歩は目撃情報を残しません。潜伏は1行動で追跡度−3、次ラウンドまでその人の発見を防ぎます。陽動は通信機1で追跡度−4、追跡隊を1ラウンド足止め。拘束の上限は、簡単4回・普通3回・難しい2回です。追跡隊の特性は作戦書で確認しましょう。</p><h3>4つの役割</h3><p>${ROLES.map(r=>`${r.icon} <strong>${r.name}</strong>：${r.perk}`).join('<br>')}</p><h3>裏切りありのルール</h3><p>2〜4人で出発前に選べます。「裏切りの選択」から、仲間を密告して個人通行証を得るか、仲間を待たず単独脱出できます。密告は1行動・1人1回。対象の潜伏を解除し、追跡隊に現在地を知らせ、追跡度を3上げます。個人通行証は自分の単独脱出時だけ追跡度の条件を免除します。出口の追跡隊には陽動が必要です。</p><p>単独脱出はAの証明書回収が必要。B・Cや仲間の集合を待たず、各出口の必要物資の半分（端数切り上げ）を共有物資から使います。残された人は続けて遊べます。未脱出が1人になれば救出も1人で実行でき、結果は個人ごとに判定します。</p><h3>協力プレイ</h3><p>1台の端末を1〜4人で交代して遊べます。「友達と遊ぶ」ではルームコードを使って最大4端末で参加できます。ホストはプレイ中も画面を開いたままにしてください。</p><p class="network-tip">難易度は簡単30・普通24・難しい18ラウンド。物資・追跡速度・拘束の上限も変わります。途中経過は端末に自動保存されます。地図の接続はゲーム用の簡略表現で、実際の運行情報や登山ルートではありません。</p>`);
const showDetailedRules=$('#rules-btn').onclick;$('#rules-btn').onclick=showHelp;
$('#credits-btn').onclick=()=>showModal(`<span class="eyebrow">DATA & CREDITS</span><h2>関東の地図から、物語を。</h2><p>舞台は東京都・神奈川県・埼玉県・千葉県・茨城県・栃木県・群馬県の7都県。全国の地図を読み込まず、関東に絞った境界ファイルを読み込みます。東京の離島は今回の舞台に含めていません。</p><h3>地理データ</h3><p><a href="https://maps.gsi.go.jp/development/ichiran.html" target="_blank" rel="noopener">国土地理院・地理院タイル（淡色地図）</a>をインターネットから表示。タイルは関東の境界と重なるものだけを取得し、表示範囲も関東に制限しています。タイルは矩形のため、県境の近くに隣県の一部が写ることがあります。Shoreline data: VMAP0, USGS (1997).</p><p>都県境界：<a href="https://github.com/dataofjapan/land" target="_blank" rel="noopener">Data of Japan / land</a>（元データ：国土数値情報、関東7都県のみ抽出・簡略化）。</p><h3>ライブラリ</h3><p><a href="https://leafletjs.com" target="_blank" rel="noopener">Leaflet 1.9.4</a>（BSD-2-Clause） / <a href="https://peerjs.com" target="_blank" rel="noopener">PeerJS 1.5.5</a>（MIT）。ライセンス全文は<a href="licenses.txt" target="_blank" rel="noopener">こちら</a>。</p><h3>ゲーム内の設定</h3><p>実在の地名を使ったフィクションです。路線は簡略化され、運休・封鎖・救援便・物資・移動時間はすべて架空です。実際の避難や移動案内には使えません。</p>`);

// The room host alone applies actions. Each connection is bound to one player slot.
function networkStatus(text){const el=$('#network-status');if(el)el.textContent=text}
function disconnect(){clearTimeout(networkTimeout);if(peer){peer.destroy();peer=null}connections.clear();online=null;lobby=[];localSlot=0}
function makeCode(){const a='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';const nums=crypto.getRandomValues(new Uint8Array(7));return Array.from(nums,n=>a[n%a.length]).join('')}
function showNetwork(){if(online){showRoomInfo();return}showModal(`<span class="eyebrow">ONLINE CO-OP / 1—4 PLAYERS</span><h2>離れていても、同じチーム。</h2><p>ホストがルームを作り、7文字のコードを仲間に伝えてください。参加者ごとに別の端末・ブラウザで開きます。</p><label class="field-label" for="net-name">あなたの名前</label><input class="form-input" id="net-name" maxlength="16" value="" placeholder="プレイヤー"><label class="field-label" for="net-role">役割</label><select class="form-input" id="net-role">${ROLES.map((r,i)=>`<option value="${i}">${r.name} — ${r.perk}</option>`).join('')}</select><div class="modal-actions"><button class="primary" id="create-room">ルームを作る ↗</button></div><label class="field-label" for="join-code" style="display:block;margin-top:20px">ルームコードで参加</label><input id="join-code" class="form-input" maxlength="7" placeholder="例：ABCD234" autocomplete="off" style="text-transform:uppercase"><button class="secondary full" id="join-room">仲間のルームに参加 →</button><div id="network-status" role="status"></div><p class="network-tip">回線によって接続できない場合は、1台での協力プレイをご利用ください。このサイトの閲覧権限がある人同士で利用できます。通信中はホストの画面を開いたままにしてください。${game?'現在の遠征は保存したまま、新しい遠征を開始します。':''}</p>`);$('#create-room').onclick=()=>createRoom($('#net-name').value,+$('#net-role').value);$('#join-room').onclick=()=>joinRoom($('#join-code').value,$('#net-name').value,+$('#net-role').value)}
$('#online-btn').onclick=showNetwork;
function peerError(err){clearTimeout(networkTimeout);const msgs={'peer-unavailable':'そのルームが見つかりません。コードとホストの接続を確認してください。','network':'接続サービスに届きません。ネットワークを確認してください。','unavailable-id':'コードが重複しました。もう一度ルームを作成してください。','webrtc':'端末間の接続ができません。この回線では1台での協力プレイをご利用ください。'};const msg=msgs[err.type]||'接続に失敗しました。通信環境を確認し、ルームを開き直してください。';networkStatus(msg);toast(msg);if(!game||!online?.started)disconnect()}
function beginPeer(id){if(!window.Peer){toast('通信ライブラリを読み込めません。1台での協力プレイを利用できます。');return null}const p=id?new Peer(id,{debug:0}):new Peer({debug:0});p.on('error',peerError);networkTimeout=setTimeout(()=>{networkStatus('接続がタイムアウトしました。ルームを開き直してください。');toast('ルームへの接続がタイムアウトしました。');if(!online?.started)disconnect()},20000);return p}
function createRoom(name,role){disconnect();networkStatus('接続サービスにルームを作っています…');const code=makeCode();online={isHost:true,code,started:false};roomSettings={difficulty,betrayal:betrayalEnabled};lobby=[{slot:0,name:name.trim().slice(0,16)||'ホスト',role}];peer=beginPeer('tokyo-escape-v3-'+code);if(!peer){online=null;return}peer.on('open',()=>{clearTimeout(networkTimeout);showLobby()});peer.on('connection',conn=>{if(online?.started||lobby.length>=4){conn.on('open',()=>{conn.send({type:'reject',message:online?.started?'この遠征は開始済みです。':'このルームは4人で満員です。'});setTimeout(()=>conn.close(),300)});return}let boundSlot=null;conn.on('data',msg=>{if(!online?.isHost||!msg||typeof msg!=='object')return;if(msg.type==='hello'&&boundSlot===null&&!online.started){const slot=[1,2,3].find(s=>!lobby.some(p=>p.slot===s));if(slot===undefined){conn.send({type:'reject',message:'このルームは満員です。'});return}boundSlot=slot;conn.gameSlot=slot;connections.set(slot,conn);lobby.push({slot,name:String(msg.name||`プレイヤー ${slot+1}`).trim().slice(0,16),role:Number.isInteger(msg.role)&&msg.role>=0&&msg.role<4?msg.role:slot});lobby.sort((a,b)=>a.slot-b.slot);broadcastLobby();showLobby()}else if(msg.type==='action'&&online.started&&game?.status==='playing'&&conn.gameSlot===game.turn&&connections.get(conn.gameSlot)===conn){if(JSON.stringify(msg.action||{}).length<500)applyAction(msg.action||{})}});conn.on('close',()=>{if(boundSlot===null)return;connections.delete(conn.gameSlot);if(!online?.started){lobby=lobby.filter(p=>p.slot!==boundSlot);broadcastLobby();if(online?.isHost)showLobby()}else{toast(`${game.players[conn.gameSlot]?.name||'仲間'}が切断されました。ホストが代わりに操作できます。`);if(game)renderGame()}});conn.on('error',()=>toast('仲間の端末との通信に問題が発生しました。'))})}
function broadcastLobby(){connections.forEach((conn,slot)=>conn.open&&conn.send({type:'lobby',lobby,slot,code:online.code,settings:roomSettings}))}
function joinRoom(code,name,role){code=code.toUpperCase().replace(/\s/g,'');if(!/^[A-HJ-NP-Z2-9]{7}$/.test(code)){networkStatus('7文字のルームコードを入力してください。');return}disconnect();networkStatus('仲間のルームに接続しています…');online={isHost:false,code,started:false};peer=beginPeer();if(!peer){online=null;return}peer.on('open',()=>{const conn=peer.connect('tokyo-escape-v3-'+code,{reliable:true});online.hostConnection=conn;conn.on('open',()=>conn.send({type:'hello',name:name.trim().slice(0,16)||'ゲスト',role}));conn.on('data',msg=>{if(!msg||typeof msg!=='object')return;if(msg.type==='reject'){networkStatus(msg.message);toast(msg.message);disconnect()}else if(msg.type==='lobby'&&Array.isArray(msg.lobby)){clearTimeout(networkTimeout);localSlot=msg.slot;lobby=msg.lobby;if(msg.settings&&Object.hasOwn(DIFFICULTIES,msg.settings.difficulty))roomSettings={difficulty:msg.settings.difficulty,betrayal:msg.settings.betrayal===true};showLobby()}else if(msg.type==='state'&&validGame(msg.state)){clearTimeout(networkTimeout);const first=!online.started;online.started=true;localSlot=msg.slot;const oldTurn=game?.turn;game=msg.state;if(oldTurn!==game.turn||navigationTarget===game.players[game.turn].pos)navigationTarget=null;if(first||oldTurn!==game.turn&&game.turn===localSlot)uiScreen='action';selected=game.players[game.turn].pos;save();closeModal();render();if(game.turn===localSlot){focusPlayer();window.scrollTo({top:0,behavior:'instant'})}if(first&&game.story)showBriefing()}});conn.on('close',()=>{if(!online)return;toast('ホストとの接続が切れました。保存データから1台で続きを遊べます。');const started=online.started;disconnect();if(started&&game)render();else showNetwork()});conn.on('error',peerError)})}
function showLobby(){if(!online||online.started)return;showModal(`<span class="eyebrow">TEAM LOBBY</span><h2>仲間の合流を待とう。</h2><p>仲間に、この7文字のコードを伝えてください。</p><div class="room-code">${escape(online.code)}</div><div class="room-members">${lobby.map((p,i)=>`<div class="room-member"><span style="color:${ROLES[p.role]?.color}">${escape(p.name)}</span><small>${ROLES[p.role]?.name} / ${i===0?'HOST':'JOINED'}</small></div>`).join('')}</div><p>${lobby.length} / 4人が参加中</p>${online.isHost?`<label class="field-label" for="net-difficulty">難易度</label><select class="form-input" id="net-difficulty">${difficultyOptions(roomSettings.difficulty)}</select><label class="field-label" for="net-betrayal">協力ルール</label><select class="form-input" id="net-betrayal"><option value="true" ${roomSettings.betrayal?'selected':''}>裏切りあり / 密告・単独脱出が可能</option><option value="false" ${!roomSettings.betrayal?'selected':''}>全員で帰る / 協力のみ</option></select><p class="network-tip">1人で開始した場合は、裏切りなしになります。</p><button class="primary" id="start-online">${lobby.length}人で出発する ↗</button>`:`<p class="waiting">難易度：${DIFFICULTIES[roomSettings.difficulty].name} / ${roomSettings.betrayal&&lobby.length>1?'裏切りあり':'全員で帰る'}<br>ホストが遠征を開始すると、自動的に行動画面へ移ります。</p>`}<div class="modal-actions"><button class="secondary" id="copy-code">コードをコピー</button><button class="secondary" id="cancel-room">ルームを離れる</button></div><div id="network-status"></div><p class="network-tip">1〜4人で開始できます。開始後の途中参加はできません。ホストは切断された仲間のキャラクターも操作できます。検知に時間がかかる場合は、待機表示の引き継ぎボタンを押してください。</p>`);$('#copy-code').onclick=async()=>{try{await navigator.clipboard.writeText(online.code);toast('ルームコードをコピーしました。')}catch{toast('表示されたコードを選択してコピーしてください。')}};$('#cancel-room').onclick=()=>{disconnect();closeModal()};if($('#net-difficulty'))$('#net-difficulty').onchange=()=>{roomSettings.difficulty=$('#net-difficulty').value;broadcastLobby()};if($('#net-betrayal'))$('#net-betrayal').onchange=()=>{roomSettings.betrayal=$('#net-betrayal').value==='true';broadcastLobby()};if($('#start-online'))$('#start-online').onclick=startOnline}
function startOnline(){const sorted=[...lobby].sort((a,b)=>a.slot-b.slot),oldConnections=new Map(connections);connections.clear();sorted.forEach((p,i)=>{if(oldConnections.has(p.slot)){const c=oldConnections.get(p.slot);c.gameSlot=i;connections.set(i,c)}p.slot=i});lobby=sorted;betrayalEnabled=roomSettings.betrayal;game=createRun(lobby.length,roomSettings.difficulty,lobby.map(p=>p.name),lobby.map(p=>p.role));online.started=true;selected='kinshicho';uiScreen='action';navigationTarget=null;save();broadcastState();closeModal();render();focusPlayer();window.scrollTo({top:0,behavior:'instant'});showBriefing()}
function broadcastState(){if(!online?.isHost||!game)return;connections.forEach((c,slot)=>{if(c.open)c.send({type:'state',state:game,slot})})}
function showRoomInfo(){if(!online){showNetwork();return}if(!online.started){showLobby();return}showModal(`<span class="eyebrow">CONNECTED TEAM</span><h2>同じ地図の上で。</h2><div class="room-code">${escape(online.code)}</div><p>あなたは ${online.isHost?'ホスト':'プレイヤー '+(localSlot+1)}。行動順が回ってきたプレイヤーが操作します。ホストは、接続が切れた仲間の操作を引き継げます。</p><p class="network-tip">遠征開始後の途中参加・再接続はできません。通信をやめる場合は「遠征を保存して戻る」を選択してください。最後に同期した遠征を1台で再開できます。</p>`)}
window.addEventListener('beforeunload',()=>{save();if(peer)peer.destroy()});
render();
